// Fill these in once. They are not secrets: keys live in n8n Credentials.
return [{
  json: {
    supabase_url: 'https://YOUR-PROJECT.supabase.co',
    clay_webhook_url: 'https://api.clay.com/v3/sources/webhook/YOUR-WEBHOOK-ID',
  },
}];

// Turn any version of a LinkedIn profile link into one standard form,
// so the same person always matches the same Supabase row.
const event = $('Slack Trigger').first().json;
const text = event.text || '';

// Slack wraps links as <https://...> or <https://...|label>.
// Also accepts m.linkedin.com and /mwlite/in/ mobile links.
const match = text.match(/linkedin\.com\/(?:mwlite\/)?in\/([^\/?#\s>|]+)/i);
const slug = match ? match[1].toLowerCase() : null;

return [{
  json: {
    valid: Boolean(slug),
    linkedin_url: slug ? `https://www.linkedin.com/in/${slug}` : null,
    sdr_slack_id: event.user,
    channel: event.channel,
    // Reply under the SDR's message (or in the thread they mentioned us in)
    thread_ts: event.thread_ts || event.ts,
  },
}];

// The person is already in Supabase: reply under the NEW mention,
// and say who owns them and where the original thread is.
const lead = $json;
const mention = $('Clean URL').first().json;

const link = lead.slack_channel_id && lead.slack_thread_ts
  ? ` · <https://slack.com/archives/${lead.slack_channel_id}/p${lead.slack_thread_ts.replace('.', '')}|original thread>`
  : '';

const note = lead.status === 'do_not_contact'
  ? ':no_entry: This person is marked *do not contact*.'
  : `:repeat: Already in the pipeline · owner <@${lead.sdr_slack_id}> · status \`${lead.status}\`${link}`;

return [{
  json: {
    ...lead,
    reply_channel: mention.channel,
    reply_thread_ts: mention.thread_ts,
    reply_note: note,
  },
}];

// Build the Slack lead card (Block Kit) from one Supabase lead row.
// Used by both paths: an existing lead (Part A) and a freshly enriched one (Part B).
const lead = $json;

const has = (v) => v !== undefined && v !== null && String(v).trim() !== '';
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const count = (v) => (has(v) ? Number(v).toLocaleString('en-US') : null);

const name = lead.full_name || lead.linkedin_url || 'New lead';

const email = has(lead.work_email)
  ? lead.work_email + (has(lead.email_status) ? ` (${lead.email_status})` : '')
  : 'Not found';

const fields = [
  ['Title', lead.title],
  ['Company', lead.company_name],
  ['Email', email],
  ['Phone', has(lead.phone) ? lead.phone : 'Not found'],
  ['Location', lead.location],
  ['Company size', lead.company_size],
  ['Industry', lead.industry],
  ['Followers', count(lead.linkedin_followers)],
  ['Connections', count(lead.linkedin_connections)],
  ['Status', lead.status],
]
  .filter(([, value]) => has(value))
  .slice(0, 10) // Slack allows at most 10 fields per section
  .map(([label, value]) => ({ type: 'mrkdwn', text: cut(`*${label}*\n${value}`, 2000) }));

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: cut(name, 150) } },
];

if (has(lead.reply_note)) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: lead.reply_note }] });
}
if (has(lead.headline)) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: cut(`_${lead.headline}_`, 3000) } });
}
if (fields.length) {
  blocks.push({ type: 'section', fields });
}
if (has(lead.research_summary)) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: cut(`*Research*\n${lead.research_summary}`, 3000) } });
}
if (has(lead.talking_points)) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: cut(`*Talking points*\n${lead.talking_points}`, 3000) } });
}
if (!has(lead.phone)) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':telephone_receiver: No phone found, start on LinkedIn' }] });
}

// The three call-outcome buttons. Each carries the lead id, so the
// workflow that handles clicks (built later) knows which lead it is.
if (lead.status !== 'do_not_contact') {
  const buttons = [
    { type: 'button', action_id: 'call_connected', style: 'primary', text: { type: 'plain_text', text: 'Picked up' }, value: lead.id },
    { type: 'button', action_id: 'call_no_answer', text: { type: 'plain_text', text: 'Did not pick up' }, value: lead.id },
    { type: 'button', action_id: 'wrong_person', style: 'danger', text: { type: 'plain_text', text: 'Wrong person' }, value: lead.id },
  ];
  if (has(lead.linkedin_url)) {
    buttons.push({ type: 'button', action_id: 'open_linkedin', text: { type: 'plain_text', text: 'LinkedIn' }, url: lead.linkedin_url });
  }
  blocks.push({ type: 'actions', block_id: 'call_outcome', elements: buttons });
}

return [{
  json: {
    channel: lead.reply_channel || lead.slack_channel_id,
    thread_ts: lead.reply_thread_ts || lead.slack_thread_ts,
    text: `Lead card: ${name}`, // fallback for notifications
    blocks,
    unfurl_links: false,
  },
}];

// Same Supabase URL as the Config node in Part A.
return [{
  json: {
    supabase_url: 'https://YOUR-PROJECT.supabase.co',
  },
}];

// Clay posts the enriched person here. Pick out the fields that have a
// Supabase column, tidy them up, and keep the full payload in `enrichment`.
const b = $('Clay results').first().json.body || {};
if (!b.lead_id) {
  throw new Error('Clay sent no lead_id. Add a lead_id key to the HTTP API column body.');
}

const text = (v) => (v === undefined || v === null || String(v).trim() === '') ? null : String(v).trim();
const num = (v) => {
  const n = parseInt(String(v ?? '').replace(/[^0-9]/g, ''), 10);
  return Number.isFinite(n) ? n : null;
};
const parseMaybeJson = (v) => {
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch { return v; }
};
// Lists (from Clay AI columns) become one bullet per line
const bullets = (v) => {
  v = parseMaybeJson(v);
  if (v === undefined || v === null || v === '') return null;
  return Array.isArray(v) ? v.map((x) => `• ${String(x).trim()}`).join('\n') : String(v).trim();
};

// The AI column may arrive as one JSON object: { summary, talking_points }
const research = parseMaybeJson(b.research) || {};

const first = text(b.first_name);
const last = text(b.last_name);

const update = {
  first_name: first,
  last_name: last,
  full_name: text(b.full_name) || [first, last].filter(Boolean).join(' ') || null,
  title: text(b.title),
  headline: text(b.headline),
  location: text(b.location),
  company_name: text(b.company_name),
  company_domain: text(b.company_domain),
  company_linkedin_url: text(b.company_linkedin_url),
  company_size: text(b.company_size),
  industry: text(b.industry),
  work_email: text(b.work_email),
  email_status: text(b.email_status),
  phone: text(b.phone),
  phone_type: text(b.phone_type),
  linkedin_followers: num(b.linkedin_followers),
  linkedin_connections: num(b.linkedin_connections),
  research_summary: bullets(b.research_summary ?? research.summary),
  talking_points: bullets(b.talking_points ?? research.talking_points),
  enrichment: b,
  status: 'enriched',
};

// Never overwrite a saved value with a blank one
for (const key of Object.keys(update)) {
  if (update[key] === null) delete update[key];
}

return [{ json: { lead_id: b.lead_id, update } }];
